import { serve } from "@hono/node-server";
import { app } from "./app";

const port = Number(process.env.PORT || 3001);

function logStartupStatus() {
  const check = (key: string) => process.env[key]?.trim() ? "configured" : "MISSING";
  console.log("--- Startup Configuration ---");
  console.log(`  APP_ENV:            ${process.env.APP_ENV ?? "not set"}`);
  console.log(`  APP_ORIGIN:         ${process.env.APP_ORIGIN ?? "not set"}`);
  console.log(`  BILLING_MODE:       ${process.env.BILLING_MODE ?? "not set"}`);
  console.log(`  Supabase URL:       ${check("NEXT_PUBLIC_SUPABASE_URL")}`);
  console.log(`  Supabase anon key:  ${check("NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY")}`);
  console.log(`  Supabase secret:    ${check("SUPABASE_SECRET_KEY")}`);
  console.log(`  RC webhook auth:    ${check("REVENUECAT_WEBHOOK_AUTHORIZATION")}`);
  console.log(`  RC secret API key:  ${check("REVENUECAT_SECRET_API_KEY")}`);
  console.log(`  Google OAuth:       ${check("SUPABASE_AUTH_GOOGLE_CLIENT_ID")}`);
  console.log(`  Apple OAuth:        ${check("SUPABASE_AUTH_APPLE_CLIENT_ID")}`);
  console.log(`  Stripe secret:      ${check("STRIPE_SECRET_KEY")}`);
  console.log("-----------------------------");
}

logStartupStatus();

serve({ fetch: app.fetch, port }, () => {
  console.log(`Auth service running on port ${port}`);
});

