import { describe, expect, it } from "vitest";
import type { RevenueCatCustomerInfo } from "@foundation/config";
import { handleGetEntitlements, handleGetEntitlement } from "./entitlements";
import { getHeader } from "./request";
import { handleRevenueCatWebhook } from "./revenuecat-webhook";
import { handleSocialAuth, isValidPlatform, isValidProvider, isValidUuid } from "./social-auth";
import { handleCreateCheckoutSession, handleCreateBillingPortal } from "./stripe-checkout";
import type {
  AppUser,
  BillingEventStore,
  DeviceInfo,
  DeviceStore,
  RevenueCatWebhookDeps,
  SocialAuthDeps,
  StripeClient,
  StripeCustomerStore,
  SubscriberCacheStore
} from "./types";

// ---------------------------------------------------------------------------
// Test factories
// ---------------------------------------------------------------------------

function auth(user: AppUser | null) {
  return { getUser: async () => user };
}

class MemoryEvents implements BillingEventStore {
  readonly records: Array<{ eventId: string; userId: string | null; payloadHash: string }> = [];
  constructor(private readonly processed = new Set<string>()) {}
  async hasProcessed(eventId: string): Promise<boolean> {
    return this.processed.has(eventId);
  }
  async record(input: { eventId: string; userId: string | null; payloadHash: string }): Promise<void> {
    this.records.push(input);
    this.processed.add(input.eventId);
  }
}

class MemorySubscriberCache implements SubscriberCacheStore {
  readonly cache = new Map<string, unknown>();
  async upsert(userId: string, rawSubscriber: unknown): Promise<void> {
    this.cache.set(userId, rawSubscriber);
  }
  async getByUserId(userId: string): Promise<unknown | null> {
    return this.cache.get(userId) ?? null;
  }
}

class MemoryDeviceStore implements DeviceStore {
  readonly devices: Array<{ userId: string; device: DeviceInfo }> = [];
  async upsert(userId: string, device: DeviceInfo): Promise<void> {
    const existing = this.devices.find(
      (d) => d.userId === userId && d.device.device_id === device.device_id
    );
    if (existing) {
      existing.device = device;
    } else {
      this.devices.push({ userId, device });
    }
  }
  async countByUserId(userId: string): Promise<number> {
    return this.devices.filter((d) => d.userId === userId).length;
  }
}

class MemoryStripeCustomerStore implements StripeCustomerStore {
  readonly customers = new Map<string, string>();
  async findByUserId(userId: string): Promise<string | null> {
    return this.customers.get(userId) ?? null;
  }
  async upsert(userId: string, stripeCustomerId: string): Promise<void> {
    this.customers.set(userId, stripeCustomerId);
  }
}

class MemoryStripeClient implements StripeClient {
  readonly createdCustomers: Array<{ email: string; metadata: Record<string, string> }> = [];
  readonly createdCheckouts: Array<Record<string, unknown>> = [];
  readonly createdPortals: Array<Record<string, unknown>> = [];

  async createCustomer(email: string, metadata: Record<string, string>): Promise<string> {
    this.createdCustomers.push({ email, metadata });
    return `cus_${this.createdCustomers.length}`;
  }
  async createCheckoutSession(params: {
    customerId: string; priceId: string; successUrl: string; cancelUrl: string;
    metadata: Record<string, string>; subscriptionMetadata: Record<string, string>;
  }): Promise<string> {
    this.createdCheckouts.push(params);
    return "https://checkout.stripe.com/session_123";
  }
  async createBillingPortalSession(params: { customerId: string; returnUrl: string }): Promise<string> {
    this.createdPortals.push(params);
    return "https://billing.stripe.com/portal_123";
  }
}

function webhookDeps(overrides: Partial<RevenueCatWebhookDeps> = {}): RevenueCatWebhookDeps {
  const customerInfo: RevenueCatCustomerInfo = {
    subscriber: {
      entitlements: { pro: { product_identifier: "monthly", expires_date: null } },
      subscriptions: { monthly: { store: "stripe" } }
    }
  };
  return {
    expectedAuthorization: "Bearer webhook",
    events: new MemoryEvents(),
    users: { findExistingUserId: async (candidates) => candidates.find((c) => c === "user-123") ?? null },
    revenueCat: { fetchCustomerInfo: async () => customerInfo },
    subscriptions: new MemorySubscriberCache(),
    ...overrides
  };
}

function socialAuthDeps(overrides: Partial<SocialAuthDeps> = {}): SocialAuthDeps {
  return {
    signInWithIdToken: async () => ({
      session: { access_token: "jwt-token", refresh_token: "refresh-token", expires_in: 3600, user_id: "user-abc" },
      error: null
    }),
    ...overrides
  };
}

const VALID_DEVICE_ID = "a1b2c3d4-e5f6-7890-abcd-ef1234567890";

// ---------------------------------------------------------------------------
// request helpers
// ---------------------------------------------------------------------------

describe("request helpers", () => {
  it("should read lowercase, exact-case, and missing headers", () => {
    expect(getHeader({ headers: { "x-test": "a" } }, "X-Test")).toBe("a");
    expect(getHeader({ headers: { "X-Test": "b" } }, "X-Test")).toBe("b");
    expect(getHeader({ headers: {} }, "X-Test")).toBeNull();
  });
});

// ---------------------------------------------------------------------------
// RevenueCat webhook handler
// ---------------------------------------------------------------------------

describe("RevenueCat webhook handler", () => {
  const payload = { event: { id: "event-1", app_user_id: "user-123" } };

  it("should reject invalid auth and malformed payloads", async () => {
    expect(await handleRevenueCatWebhook({ headers: { authorization: "Bearer bad" }, body: payload }, webhookDeps())).toMatchObject({ status: 401 });
    expect(await handleRevenueCatWebhook({ headers: { authorization: "Bearer webhook" }, body: { event: {} } }, webhookDeps())).toMatchObject({
      status: 400,
      body: { error: "RevenueCat event id is required" }
    });
  });

  it("should ignore duplicate events", async () => {
    expect(
      await handleRevenueCatWebhook(
        { headers: { authorization: "Bearer webhook" }, body: payload },
        webhookDeps({ events: new MemoryEvents(new Set(["event-1"])) })
      )
    ).toEqual({ status: 200, body: { duplicate: true } });
  });

  it("should record unmatched events without syncing", async () => {
    const events = new MemoryEvents();
    const response = await handleRevenueCatWebhook(
      { headers: { authorization: "Bearer webhook" }, body: { event: { id: "event-2", app_user_id: "unknown" } } },
      webhookDeps({ events })
    );
    expect(response).toEqual({ status: 200, body: { synced: false, reason: "No matching user" } });
    expect(events.records[0]?.userId).toBeNull();
  });

  it("should cache raw subscriber info for matched users", async () => {
    const subscriptions = new MemorySubscriberCache();
    const response = await handleRevenueCatWebhook(
      { headers: { authorization: "Bearer webhook" }, body: payload },
      webhookDeps({ subscriptions })
    );
    expect(response).toEqual({ status: 200, body: { synced: true } });
    const cached = subscriptions.cache.get("user-123") as RevenueCatCustomerInfo;
    expect(cached.subscriber?.entitlements).toHaveProperty("pro");
  });
});

// ---------------------------------------------------------------------------
// Provider validation
// ---------------------------------------------------------------------------

describe("provider validation", () => {
  it("should accept apple and google as valid providers", () => {
    expect(isValidProvider("apple")).toBe(true);
    expect(isValidProvider("google")).toBe(true);
  });

  it("should reject unknown strings, empty values, and non-strings", () => {
    expect(isValidProvider("facebook")).toBe(false);
    expect(isValidProvider("")).toBe(false);
    expect(isValidProvider(undefined)).toBe(false);
    expect(isValidProvider(null)).toBe(false);
    expect(isValidProvider(42)).toBe(false);
  });
});

// ---------------------------------------------------------------------------
// Platform validation
// ---------------------------------------------------------------------------

describe("platform validation", () => {
  it("should accept ios, android, and web as valid platforms", () => {
    expect(isValidPlatform("ios")).toBe(true);
    expect(isValidPlatform("android")).toBe(true);
    expect(isValidPlatform("web")).toBe(true);
  });

  it("should reject unknown strings, empty values, and non-strings", () => {
    expect(isValidPlatform("linux")).toBe(false);
    expect(isValidPlatform("")).toBe(false);
    expect(isValidPlatform(undefined)).toBe(false);
    expect(isValidPlatform(null)).toBe(false);
    expect(isValidPlatform(42)).toBe(false);
  });
});

// ---------------------------------------------------------------------------
// UUID validation
// ---------------------------------------------------------------------------

describe("UUID validation", () => {
  it("should accept valid UUIDs", () => {
    expect(isValidUuid("a1b2c3d4-e5f6-7890-abcd-ef1234567890")).toBe(true);
    expect(isValidUuid("A1B2C3D4-E5F6-7890-ABCD-EF1234567890")).toBe(true);
  });

  it("should reject invalid UUIDs and non-strings", () => {
    expect(isValidUuid("not-a-uuid")).toBe(false);
    expect(isValidUuid("")).toBe(false);
    expect(isValidUuid(undefined)).toBe(false);
    expect(isValidUuid(123)).toBe(false);
  });
});

// ---------------------------------------------------------------------------
// Social auth handler
// ---------------------------------------------------------------------------

describe("social auth handler", () => {
  it("should return 400 when provider is missing", async () => {
    const result = await handleSocialAuth({ token: "id-token" }, socialAuthDeps());
    expect(result.status).toBe(400);
  });

  it("should return 400 when provider is not supported", async () => {
    const result = await handleSocialAuth({ provider: "facebook", token: "id-token" }, socialAuthDeps());
    expect(result.status).toBe(400);
  });

  it("should return 400 when token is missing", async () => {
    const result = await handleSocialAuth({ provider: "google" }, socialAuthDeps());
    expect(result.status).toBe(400);
  });

  it("should return 400 when token is empty string", async () => {
    const result = await handleSocialAuth({ provider: "google", token: "  " }, socialAuthDeps());
    expect(result.status).toBe(400);
  });

  it("should return 401 when signInWithIdToken returns an error", async () => {
    const deps = socialAuthDeps({
      signInWithIdToken: async () => ({ session: null, error: "Invalid token" })
    });
    const result = await handleSocialAuth({ provider: "google", token: "bad-token" }, deps);
    expect(result).toMatchObject({ status: 401, body: { error: "Authentication failed" } });
  });

  it("should return 401 when signInWithIdToken returns no session", async () => {
    const deps = socialAuthDeps({
      signInWithIdToken: async () => ({ session: null, error: null })
    });
    const result = await handleSocialAuth({ provider: "apple", token: "some-token" }, deps);
    expect(result).toMatchObject({ status: 401, body: { error: "Authentication failed" } });
  });

  it("should return tokens for valid apple auth", async () => {
    const result = await handleSocialAuth({ provider: "apple", token: "valid-apple-token" }, socialAuthDeps());
    expect(result).toEqual({
      status: 200,
      body: { access_token: "jwt-token", refresh_token: "refresh-token", expires_in: 3600 }
    });
  });

  it("should return tokens for valid google auth", async () => {
    const result = await handleSocialAuth({ provider: "google", token: "valid-google-token" }, socialAuthDeps());
    expect(result).toEqual({
      status: 200,
      body: { access_token: "jwt-token", refresh_token: "refresh-token", expires_in: 3600 }
    });
  });

  it("should pass nonce and access_token to signInWithIdToken when provided", async () => {
    let capturedOptions: { nonce?: string; access_token?: string } | undefined;
    const deps = socialAuthDeps({
      signInWithIdToken: async (_provider, _token, options) => {
        capturedOptions = options;
        return { session: { access_token: "jwt", refresh_token: "rt", expires_in: 3600, user_id: "u" }, error: null };
      }
    });
    await handleSocialAuth({ provider: "google", token: "tok", nonce: "my-nonce", access_token: "at" }, deps);
    expect(capturedOptions).toEqual({ nonce: "my-nonce", access_token: "at" });
  });

  it("should handle null and undefined body gracefully", async () => {
    expect((await handleSocialAuth(null, socialAuthDeps())).status).toBe(400);
    expect((await handleSocialAuth(undefined, socialAuthDeps())).status).toBe(400);
  });

  // Device tracking tests

  it("should record device and return device_count on successful auth", async () => {
    const devices = new MemoryDeviceStore();
    const deps = socialAuthDeps({ devices });
    const result = await handleSocialAuth(
      { provider: "google", token: "tok", device_id: VALID_DEVICE_ID, platform: "ios" },
      deps
    );
    expect(result.status).toBe(200);
    expect((result.body as Record<string, unknown>).device_count).toBe(1);
    expect(devices.devices).toHaveLength(1);
  });

  it("should update existing device on repeat auth (upsert)", async () => {
    const devices = new MemoryDeviceStore();
    const deps = socialAuthDeps({ devices });
    await handleSocialAuth({ provider: "google", token: "tok", device_id: VALID_DEVICE_ID, platform: "ios" }, deps);
    await handleSocialAuth({ provider: "google", token: "tok", device_id: VALID_DEVICE_ID, platform: "ios" }, deps);
    expect(devices.devices).toHaveLength(1);
    expect((await handleSocialAuth({ provider: "google", token: "tok", device_id: VALID_DEVICE_ID, platform: "ios" }, deps)).body).toMatchObject({ device_count: 1 });
  });

  it("should return device_count reflecting multiple devices", async () => {
    const devices = new MemoryDeviceStore();
    devices.devices.push({ userId: "user-abc", device: { device_id: "00000000-0000-0000-0000-000000000001", platform: "web" } });
    const deps = socialAuthDeps({ devices });
    const result = await handleSocialAuth(
      { provider: "google", token: "tok", device_id: VALID_DEVICE_ID, platform: "android" },
      deps
    );
    expect((result.body as Record<string, unknown>).device_count).toBe(2);
  });

  it("should skip device tracking when device_id is missing", async () => {
    const devices = new MemoryDeviceStore();
    const result = await handleSocialAuth({ provider: "google", token: "tok", platform: "ios" }, socialAuthDeps({ devices }));
    expect(result.status).toBe(200);
    expect((result.body as Record<string, unknown>).device_count).toBeUndefined();
    expect(devices.devices).toHaveLength(0);
  });

  it("should skip device tracking when platform is missing", async () => {
    const devices = new MemoryDeviceStore();
    const result = await handleSocialAuth({ provider: "google", token: "tok", device_id: VALID_DEVICE_ID }, socialAuthDeps({ devices }));
    expect((result.body as Record<string, unknown>).device_count).toBeUndefined();
  });

  it("should skip device tracking when platform is invalid", async () => {
    const devices = new MemoryDeviceStore();
    const result = await handleSocialAuth({ provider: "google", token: "tok", device_id: VALID_DEVICE_ID, platform: "linux" }, socialAuthDeps({ devices }));
    expect((result.body as Record<string, unknown>).device_count).toBeUndefined();
  });

  it("should skip device tracking when device_id is not a valid UUID", async () => {
    const devices = new MemoryDeviceStore();
    const result = await handleSocialAuth({ provider: "google", token: "tok", device_id: "not-a-uuid", platform: "ios" }, socialAuthDeps({ devices }));
    expect((result.body as Record<string, unknown>).device_count).toBeUndefined();
    expect(devices.devices).toHaveLength(0);
  });

  it("should skip device tracking when deps.devices is not provided", async () => {
    const result = await handleSocialAuth(
      { provider: "google", token: "tok", device_id: VALID_DEVICE_ID, platform: "ios" },
      socialAuthDeps()
    );
    expect(result.status).toBe(200);
    expect((result.body as Record<string, unknown>).device_count).toBeUndefined();
  });

  it("should include device_name when provided", async () => {
    const devices = new MemoryDeviceStore();
    await handleSocialAuth(
      { provider: "google", token: "tok", device_id: VALID_DEVICE_ID, platform: "ios", device_name: "My iPhone" },
      socialAuthDeps({ devices })
    );
    expect(devices.devices[0]?.device.device_name).toBe("My iPhone");
  });

  it("should not track device on failed auth", async () => {
    const devices = new MemoryDeviceStore();
    const deps = socialAuthDeps({
      signInWithIdToken: async () => ({ session: null, error: "Invalid" }),
      devices
    });
    const result = await handleSocialAuth(
      { provider: "google", token: "bad", device_id: VALID_DEVICE_ID, platform: "ios" },
      deps
    );
    expect(result.status).toBe(401);
    expect(devices.devices).toHaveLength(0);
  });
});

