describe("entitlements handler", () => {
  const subscriberWithEntitlements: RevenueCatCustomerInfo = {
    subscriber: {
      entitlements: {
        plant_id_pro: { product_identifier: "plant_monthly", expires_date: null },
        bird_id_pro: { product_identifier: "all_apps_bundle", expires_date: null }
      },
      subscriptions: {
        plant_monthly: { store: "app_store" },
        all_apps_bundle: { store: "app_store" }
      }
    }
  };

  function entitlementsDeps(user: AppUser | null, rawSubscriber: unknown | null = null) {
    const cache = new MemorySubscriberCache();
    if (user && rawSubscriber) {
      cache.cache.set(user.id, rawSubscriber);
    }
    return { auth: auth(user), subscriptions: cache };
  }

  it("should return 401 when not authenticated", async () => {
    const result = await handleGetEntitlements({ headers: {} }, entitlementsDeps(null));
    expect(result.status).toBe(401);
  });

  it("should return empty array when user has no subscription data", async () => {
    const result = await handleGetEntitlements({ headers: {} }, entitlementsDeps({ id: "user-1", email: null }));
    expect(result).toEqual({ status: 200, body: { entitlements: [] } });
  });

  it("should return all entitlements from cached subscriber snapshot", async () => {
    const user = { id: "user-1", email: "u@test.com" };
    const result = await handleGetEntitlements({ headers: {} }, entitlementsDeps(user, subscriberWithEntitlements));
    expect(result.status).toBe(200);
    const body = result.body as { entitlements: Array<{ entitlementId: string }> };
    expect(body.entitlements).toHaveLength(2);
    expect(body.entitlements.map((e) => e.entitlementId).sort()).toEqual(["bird_id_pro", "plant_id_pro"]);
  });

  it("should return specific entitlement by id", async () => {
    const user = { id: "user-1", email: null };
    const result = await handleGetEntitlement("plant_id_pro", { headers: {} }, entitlementsDeps(user, subscriberWithEntitlements));
    expect(result.status).toBe(200);
    expect((result.body as { entitlementId: string }).entitlementId).toBe("plant_id_pro");
  });

  it("should return 404 for unknown entitlement id", async () => {
    const user = { id: "user-1", email: null };
    const result = await handleGetEntitlement("unknown", { headers: {} }, entitlementsDeps(user, subscriberWithEntitlements));
    expect(result.status).toBe(404);
  });

  it("should return 404 when user has no cached data and specific entitlement requested", async () => {
    const user = { id: "user-1", email: null };
    const result = await handleGetEntitlement("pro", { headers: {} }, entitlementsDeps(user));
    expect(result.status).toBe(404);
  });

  it("should return 401 for specific entitlement when not authenticated", async () => {
    const result = await handleGetEntitlement("pro", { headers: {} }, entitlementsDeps(null));
    expect(result.status).toBe(401);
  });
});

