  it("should return 404 when no Stripe customer exists", async () => {
    const result = await handleCreateBillingPortal({ headers: {}, body: validBody }, portalDeps(user));
    expect(result.status).toBe(404);
    expect((result.body as Record<string, unknown>).error).toContain("billing account");
  });

  it("should return 400 for invalid returnUrl", async () => {
    const customers = new MemoryStripeCustomerStore();
    customers.customers.set("user-1", "cus_existing");
    const result = await handleCreateBillingPortal(
      { headers: {}, body: { returnUrl: "not-a-url" } },
