  it("should return 400 for missing returnUrl", async () => {
    const customers = new MemoryStripeCustomerStore();
    customers.customers.set("user-1", "cus_existing");
    const result = await handleCreateBillingPortal(
      { headers: {}, body: {} },
      portalDeps(user, { customers })
    );
    expect(result.status).toBe(400);
  });

  it("should return 400 for null body", async () => {
    const customers = new MemoryStripeCustomerStore();
    customers.customers.set("user-1", "cus_existing");
    const result = await handleCreateBillingPortal(
      { headers: {}, body: null },
      portalDeps(user, { customers })
    );
    expect(result.status).toBe(400);
  });

  it("should return portal URL for existing customer", async () => {
    const customers = new MemoryStripeCustomerStore();
    customers.customers.set("user-1", "cus_existing");
    const stripe = new MemoryStripeClient();
    const result = await handleCreateBillingPortal(
      { headers: {}, body: validBody },
      portalDeps(user, { customers, stripe })
    );
    expect(result.status).toBe(200);
    expect((result.body as Record<string, unknown>).portalUrl).toBe("https://billing.stripe.com/portal_123");
    expect(stripe.createdPortals[0]).toMatchObject({
      customerId: "cus_existing",
      returnUrl: "https://app.example.com/account",
    });
  });
});

