import type { AppRequest, AppResponse, CheckoutSessionDeps, BillingPortalDeps } from "./types";

const STRIPE_PRICE_RE = /^price_[a-zA-Z0-9]+$/;

function isValidUrl(value: unknown): value is string {
  if (typeof value !== "string" || !value.trim()) return false;
  try {
    const parsed = new URL(value);
    return parsed.protocol === "https:" || parsed.protocol === "http:";
  } catch {
    return false;
  }
}

export async function handleCreateCheckoutSession(
  request: AppRequest,
  deps: CheckoutSessionDeps
): Promise<AppResponse> {
  const user = await deps.auth.getUser();
  if (!user) {
    return { status: 401, body: { error: "Authentication required" } };
  }

  const input = request.body as Record<string, unknown> | null | undefined;
  const priceId = input?.priceId;
  if (typeof priceId !== "string" || !STRIPE_PRICE_RE.test(priceId)) {
    return { status: 400, body: { error: "Invalid priceId. Must be a Stripe price ID (price_...)" } };
  }

  const successUrl = input?.successUrl;
  if (!isValidUrl(successUrl)) {
    return { status: 400, body: { error: "Valid successUrl is required" } };
  }

  const cancelUrl = input?.cancelUrl;
  if (!isValidUrl(cancelUrl)) {
    return { status: 400, body: { error: "Valid cancelUrl is required" } };
  }

  let customerId = await deps.customers.findByUserId(user.id);
  if (!customerId) {
    customerId = await deps.stripe.createCustomer(user.email ?? "", { supabase_user_id: user.id });
    await deps.customers.upsert(user.id, customerId);
  }

  const checkoutUrl = await deps.stripe.createCheckoutSession({
    customerId,
    priceId,
    successUrl,
    cancelUrl,
    metadata: { supabase_user_id: user.id },
    subscriptionMetadata: { supabase_user_id: user.id },
  });

  return { status: 200, body: { checkoutUrl } };
}

export async function handleCreateBillingPortal(
  request: AppRequest,
  deps: BillingPortalDeps
): Promise<AppResponse> {
  const user = await deps.auth.getUser();
  if (!user) {
    return { status: 401, body: { error: "Authentication required" } };
  }

  const customerId = await deps.customers.findByUserId(user.id);
  if (!customerId) {
    return { status: 404, body: { error: "No billing account found" } };
  }

  const input = request.body as Record<string, unknown> | null | undefined;
  const returnUrl = input?.returnUrl;
  if (!isValidUrl(returnUrl)) {
    return { status: 400, body: { error: "Valid returnUrl is required" } };
  }

  const portalUrl = await deps.stripe.createBillingPortalSession({
    customerId,
    returnUrl,
  });

  return { status: 200, body: { portalUrl } };
}

