import type { RevenueCatCustomerInfo, RevenueCatWebhookPayload } from "@foundation/config";

export const OAUTH_PROVIDERS = ["apple", "google"] as const;
export type OAuthProvider = typeof OAUTH_PROVIDERS[number];

export const DEVICE_PLATFORMS = ["ios", "android", "web"] as const;
export type DevicePlatform = typeof DEVICE_PLATFORMS[number];

export interface AppUser {
  id: string;
  email: string | null;
}

export interface AppRequest {
  headers: Record<string, string | undefined>;
  body?: unknown;
}

export interface AppResponse {
  status: number;
  headers?: Record<string, string>;
  body?: unknown;
}

export interface AuthReader {
  getUser(): Promise<AppUser | null>;
}

export interface DeviceInfo {
  device_id: string;
  platform: DevicePlatform;
  device_name?: string;
}

export interface DeviceStore {
  upsert(userId: string, device: DeviceInfo): Promise<void>;
  countByUserId(userId: string): Promise<number>;
}

export interface SocialAuthDeps {
  signInWithIdToken(
    provider: OAuthProvider,
    token: string,
    options?: { nonce?: string; access_token?: string }
  ): Promise<{
    session: { access_token: string; refresh_token: string; expires_in: number; user_id: string } | null;
    error: string | null;
  }>;
  devices?: DeviceStore;
}

export interface BillingEventStore {
  hasProcessed(eventId: string): Promise<boolean>;
  record(input: {
    eventId: string;
    userId: string | null;
    payloadHash: string;
    payload: RevenueCatWebhookPayload;
  }): Promise<void>;
}

export interface UserDirectory {
  findExistingUserId(candidates: string[]): Promise<string | null>;
}

export interface RevenueCatClient {
  fetchCustomerInfo(userId: string): Promise<RevenueCatCustomerInfo>;
}

export interface SubscriberCacheStore {
  upsert(userId: string, rawSubscriber: unknown): Promise<void>;
