import Stripe from "stripe";
import type {
  AppUser,
  AuthReader,
  BillingEventStore,
  DeviceInfo,
  DeviceStore,
  RevenueCatClient,
  RevenueCatWebhookDeps,
  StripeClient,
  StripeCustomerStore,
  SubscriberCacheStore,
  UserDirectory
} from "@/lib/api/types";
import type { RevenueCatCustomerInfo, RevenueCatWebhookPayload } from "@foundation/config";
import { createSupabaseClientFromToken, createSupabaseServiceClient } from "./server";
import { getServerEnv } from "@/lib/env";

export function createAuthReader(token: string): AuthReader {
  return {
    async getUser(): Promise<AppUser | null> {
      const supabase = createSupabaseClientFromToken(token);
      const { data, error } = await supabase.auth.getUser();
      if (error || !data.user) return null;
      return { id: data.user.id, email: data.user.email ?? null };
    }
  };
}

export function createUserDirectory(): UserDirectory {
  return {
    async findExistingUserId(candidates: string[]): Promise<string | null> {
      if (candidates.length === 0) return null;
      const supabase = createSupabaseServiceClient();
      const { data } = await supabase.auth.admin.getUserById(candidates[0]);
      return data.user ? data.user.id : null;
    }
  };
}

export function createBillingEventStore(): BillingEventStore {
  return {
    async hasProcessed(eventId: string): Promise<boolean> {
      const supabase = createSupabaseServiceClient();
      const { data } = await supabase.from("billing_events").select("event_id").eq("event_id", eventId).maybeSingle();
      return !!data;
    },
    async record(input: { eventId: string; userId: string | null; payloadHash: string; payload: RevenueCatWebhookPayload }): Promise<void> {
      const supabase = createSupabaseServiceClient();
      await supabase.from("billing_events").insert({
        event_id: input.eventId,
        user_id: input.userId,
        event_type: input.payload.event?.id ?? "unknown",
        raw_payload_hash: input.payloadHash,
        raw_payload: input.payload
      });
    }
  };
}

export function createSubscriberCacheStore(): SubscriberCacheStore {
  return {
    async upsert(userId: string, rawSubscriber: unknown): Promise<void> {
      const supabase = createSupabaseServiceClient();
      await supabase.from("subscriber_cache").upsert({
        user_id: userId,
        raw_subscriber: rawSubscriber,
        last_synced_at: new Date().toISOString(),
        updated_at: new Date().toISOString()
      });
    },
    async getByUserId(userId: string): Promise<unknown | null> {
      const supabase = createSupabaseServiceClient();
      const { data } = await supabase.from("subscriber_cache").select("raw_subscriber").eq("user_id", userId).maybeSingle();
      return data?.raw_subscriber ?? null;
    }
  };
}

export function createDeviceStore(): DeviceStore {
  return {
    async upsert(userId: string, device: DeviceInfo): Promise<void> {
      const supabase = createSupabaseServiceClient();
      await supabase.from("user_devices").upsert(
        {
          device_id: device.device_id,
          user_id: userId,
          platform: device.platform,
          device_name: device.device_name ?? null,
          last_seen_at: new Date().toISOString()
        },
        { onConflict: "device_id,user_id" }
      );
    },
    async countByUserId(userId: string): Promise<number> {
      const supabase = createSupabaseServiceClient();
      const { count } = await supabase
        .from("user_devices")
        .select("*", { count: "exact", head: true })
        .eq("user_id", userId);
      return count ?? 0;
    }
  };
}

export function createRevenueCatClient(): RevenueCatClient {
  return {
    async fetchCustomerInfo(userId: string): Promise<RevenueCatCustomerInfo> {
      const { revenueCatSecretApiKey } = getServerEnv();
      const response = await fetch(`https://api.revenuecat.com/v1/subscribers/${encodeURIComponent(userId)}`, {
        headers: { Authorization: `Bearer ${revenueCatSecretApiKey}` }
      });
      if (!response.ok) throw new Error(`RevenueCat request failed: ${response.status}`);
      const data = await response.json();
      return data.value ?? data;
    }
  };
}

export function createRevenueCatWebhookDeps(): RevenueCatWebhookDeps {
  const { runtime } = getServerEnv();
  return {
    expectedAuthorization: runtime.revenueCatWebhookAuthorization,
    events: createBillingEventStore(),
    users: createUserDirectory(),
    revenueCat: createRevenueCatClient(),
    subscriptions: createSubscriberCacheStore()
  };
}

export function createStripeCustomerStore(): StripeCustomerStore {
  return {
    async findByUserId(userId: string): Promise<string | null> {
      const supabase = createSupabaseServiceClient();
      const { data } = await supabase
        .from("stripe_customers")
        .select("stripe_customer_id")
        .eq("user_id", userId)
        .maybeSingle();
      return data?.stripe_customer_id ?? null;
    },
    async upsert(userId: string, stripeCustomerId: string): Promise<void> {
      const supabase = createSupabaseServiceClient();
      await supabase.from("stripe_customers").upsert({
        user_id: userId,
        stripe_customer_id: stripeCustomerId,
        updated_at: new Date().toISOString(),
      });
    },
  };
}

export function createStripeClient(): StripeClient {
  const { runtime } = getServerEnv();
  const stripe = new Stripe(runtime.stripeSecretKey);
  return {
    async createCustomer(email: string, metadata: Record<string, string>): Promise<string> {
      const customer = await stripe.customers.create({ email, metadata });
      return customer.id;
    },
    async createCheckoutSession(params): Promise<string> {
      const session = await stripe.checkout.sessions.create({
        customer: params.customerId,
        mode: "subscription",
        line_items: [{ price: params.priceId, quantity: 1 }],
        success_url: params.successUrl,
        cancel_url: params.cancelUrl,
        metadata: params.metadata,
        subscription_data: { metadata: params.subscriptionMetadata },
      });
      if (!session.url) {
        throw new Error("Stripe Checkout Session returned no URL");
      }
      return session.url;
    },
    async createBillingPortalSession(params): Promise<string> {
      const session = await stripe.billingPortal.sessions.create({
        customer: params.customerId,
        return_url: params.returnUrl,
      });
      return session.url;
    },
  };
}

