import { Hono } from "hono";
import { handleCreateCheckoutSession, handleCreateBillingPortal } from "../lib/api/stripe-checkout";
import { createAuthReader, createStripeCustomerStore, createStripeClient } from "../lib/supabase/repositories";

const stripeRoute = new Hono();

function getBearerToken(c: { req: { header: (name: string) => string | undefined } }): string {
  const header = c.req.header("authorization") ?? "";
  return header.startsWith("Bearer ") ? header.slice(7) : "";
}

stripeRoute.post("/checkout-session", async (c) => {
  console.log("[me/checkout-session] Creating checkout session");
  const token = getBearerToken(c);
  const body = await c.req.json();
  const result = await handleCreateCheckoutSession(
    { headers: {}, body },
    { auth: createAuthReader(token), customers: createStripeCustomerStore(), stripe: createStripeClient() }
  );
  console.log(`[me/checkout-session] Response status=${result.status}`);
  return c.json(result.body, result.status as never);
});

stripeRoute.post("/billing-portal", async (c) => {
  console.log("[me/billing-portal] Creating billing portal session");
  const token = getBearerToken(c);
  const body = await c.req.json();
  const result = await handleCreateBillingPortal(
    { headers: {}, body },
    { auth: createAuthReader(token), customers: createStripeCustomerStore(), stripe: createStripeClient() }
  );
  console.log(`[me/billing-portal] Response status=${result.status}`);
  return c.json(result.body, result.status as never);
});

export { stripeRoute };

