import { normalizeOrigin } from "./product";

export type AppEnv = "local" | "development" | "staging" | "production";
export type BillingMode = "mock" | "revenuecat_sandbox" | "revenuecat_live";

export interface RuntimeEnv {
  appEnv: AppEnv;
  appOrigin: string;
  billingMode: BillingMode;
  supabaseUrl: string;
  supabasePublishableKey: string;
  supabaseSecretKey: string;
  revenueCatWebhookAuthorization: string;
  revenueCatPurchaseLinkSandbox: string;
  revenueCatPurchaseLinkLive: string;
  cfVerifySecret: string;
  redisUrl: string;
  stripeSecretKey: string;
}

const appEnvs = new Set<AppEnv>(["local", "development", "staging", "production"]);
const billingModes = new Set<BillingMode>(["mock", "revenuecat_sandbox", "revenuecat_live"]);

function requireEnum<T extends string>(value: string | undefined, allowed: Set<T>, fallback: T): T {
  const candidate = value ?? fallback;
  if (!allowed.has(candidate as T)) {
    throw new Error(`Unsupported value: ${candidate}`);
  }
  return candidate as T;
}

function requireValue(raw: Record<string, string | undefined>, key: string): string {
  const value = raw[key]?.trim();
  if (!value) {
    throw new Error(`Missing required environment value: ${key}`);
  }
  return value;
}

export function parseRuntimeEnv(raw: Record<string, string | undefined>): RuntimeEnv {
  const env: RuntimeEnv = {
    appEnv: requireEnum(raw.APP_ENV, appEnvs, "local"),
    appOrigin: normalizeOrigin(requireValue(raw, "APP_ORIGIN")),
    billingMode: requireEnum(raw.BILLING_MODE, billingModes, "mock"),
    supabaseUrl: requireValue(raw, "NEXT_PUBLIC_SUPABASE_URL"),
    supabasePublishableKey: requireValue(raw, "NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY"),
    supabaseSecretKey: requireValue(raw, "SUPABASE_SECRET_KEY"),
    revenueCatWebhookAuthorization: requireValue(raw, "REVENUECAT_WEBHOOK_AUTHORIZATION"),
    revenueCatPurchaseLinkSandbox: raw.REVENUECAT_PURCHASE_LINK_SANDBOX?.trim() ?? "",
    revenueCatPurchaseLinkLive: raw.REVENUECAT_PURCHASE_LINK_LIVE?.trim() ?? "",
    cfVerifySecret: raw.CF_VERIFY_SECRET?.trim() ?? "",
    redisUrl: raw.REDIS_URL?.trim() ?? "",
    stripeSecretKey: raw.STRIPE_SECRET_KEY?.trim() ?? ""
  };
  const errors = validateRuntimeEnv(env);
  if (errors.length > 0) {
    throw new Error(errors.join("; "));
  }
  return env;
}

export function isLocalOrigin(origin: string): boolean {
  const host = new URL(origin).hostname;
  return host === "localhost" || host === "127.0.0.1" || host === "::1";
}

export function validateRuntimeEnv(env: RuntimeEnv): string[] {
  const errors: string[] = [];
  if (env.billingMode === "revenuecat_sandbox" && !env.revenueCatPurchaseLinkSandbox) {
    errors.push("RevenueCat sandbox purchase link is required in sandbox billing mode");
  }
  if (env.billingMode === "revenuecat_live" && !env.revenueCatPurchaseLinkLive) {
    errors.push("RevenueCat live purchase link is required in live billing mode");
  }
  if (env.appEnv === "production") {
    if (env.billingMode !== "revenuecat_live") {
      errors.push("Production must use revenuecat_live billing mode");
    }
    if (isLocalOrigin(env.appOrigin)) {
      errors.push("Production origins cannot use localhost");
    }
    if (env.revenueCatPurchaseLinkLive.includes("sandbox") || env.revenueCatPurchaseLinkLive.includes("test")) {
      errors.push("Production live purchase link cannot look like a sandbox/test link");
    }
    if (env.revenueCatPurchaseLinkSandbox && env.revenueCatPurchaseLinkSandbox === env.revenueCatPurchaseLinkLive) {
      errors.push("Sandbox and live RevenueCat purchase links must differ");
    }
    if (!env.cfVerifySecret) {
      errors.push("CF_VERIFY_SECRET is required in production");
    }
    if (!env.redisUrl) {
      errors.push("REDIS_URL is required in production");
    }
    if (!env.stripeSecretKey) {
      errors.push("STRIPE_SECRET_KEY is required in production");
    }
  }
  return errors;
}

create table public.stripe_customers (
  user_id            uuid primary key references auth.users(id) on delete cascade,
  stripe_customer_id text not null unique,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);

alter table public.stripe_customers enable row level security;

create policy "Users can read own stripe customer"
  on public.stripe_customers for select
  using (auth.uid() = user_id);

create trigger stripe_customers_touch_updated_at
  before update on public.stripe_customers
  for each row execute function public.touch_updated_at();
